import pathlib,tarfile,hashlib,json,base64
root=pathlib.Path('/dataset/shaoshitong/search-r1-rl/bapo-rewardfix-numeric');run=root/'runs/bapo-hardware-3086'
assert (run/'HARDWARE_MEASUREMENTS_RETURNED_SUCCESSFULLY').exists()
assert json.loads((run/'own-process-cleanup.json').read_text())['remaining']==[]
p=root/'logs/hardware3086-terminal-slurm.log';b=base64.b64decode('')
if p.exists():assert p.read_bytes()==b
else:p.write_bytes(b)
paths=sorted(p for p in run.iterdir() if p.is_file())+sorted((run/'numeric-fixture').glob('rank-*.json'))
assert len(list((run/'numeric-fixture').glob('rank-*.json')))==8
archive=root/'logs/bapo-numericfix-hardware3086-raw-measurements.tar.gz'
assert not archive.exists()
with tarfile.open(archive,'w:gz') as t:
 for p in paths:
  assert not p.is_symlink()
  t.add(p,arcname='bapo-hardware-3086/'+str(p.relative_to(run)),recursive=False)
record=dict(path=str(archive),bytes=archive.stat().st_size,sha256=hashlib.sha256(archive.read_bytes()).hexdigest(),files=len(paths),scope='NEW_1CC_NATIVE8_HARDWARE_RAW_NO_CACHE')
(root/'logs/hardware3086-archive-manifest.json').write_text(json.dumps(record,indent=2)+'\n')
print(json.dumps(record))
